create extension if not exists pgcrypto;
create table if not exists public.ig_profiles(user_id uuid primary key references auth.users(id) on delete cascade,instagram_username text,session_ready boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.scan_snapshots(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,follower_count integer not null default 0,followers text[] not null default '{}',unfollowers text[] not null default '{}',new_followers text[] not null default '{}',status text not null default 'complete',error_message text,created_at timestamptz not null default now());
create table if not exists public.scan_jobs(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,status text not null default 'queued',progress integer not null default 0,error_message text,created_at timestamptz not null default now(),finished_at timestamptz);
create table if not exists public.ig_secrets(user_id uuid primary key references auth.users(id) on delete cascade,session_blob text not null,updated_at timestamptz not null default now());
alter table public.ig_profiles enable row level security;alter table public.scan_snapshots enable row level security;alter table public.scan_jobs enable row level security;alter table public.ig_secrets enable row level security;
drop policy if exists ig_profiles_self on public.ig_profiles;create policy ig_profiles_self on public.ig_profiles for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
drop policy if exists scan_snapshots_self on public.scan_snapshots;create policy scan_snapshots_self on public.scan_snapshots for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
drop policy if exists scan_jobs_self on public.scan_jobs;create policy scan_jobs_self on public.scan_jobs for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create index if not exists scan_snapshots_user_time_idx on public.scan_snapshots(user_id,created_at desc);create index if not exists scan_jobs_user_time_idx on public.scan_jobs(user_id,created_at desc);